-- =============================================================================
-- 07_seed_ai_db.sql : AI CAREER SERVICE SEED DATA (ai_db)
-- Khớp 100% JobRecommendation.java + ChatSession, ChatMessage, CVReview, AIUsageLog, AIUserQuota
-- =============================================================================

CREATE TABLE IF NOT EXISTS job_recommendations (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL,
    job_id UUID NOT NULL,
    score DOUBLE PRECISION NOT NULL,
    explanation VARCHAR(1000) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    input_hash VARCHAR(64) NOT NULL,
    CONSTRAINT uk_job_recommendations_user_job UNIQUE (user_id, job_id)
);

CREATE TABLE IF NOT EXISTS ai_chat_sessions (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL,
    title VARCHAR(255) NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS ai_chat_messages (
    id UUID PRIMARY KEY,
    session_id UUID NOT NULL REFERENCES ai_chat_sessions(id) ON DELETE CASCADE,
    role VARCHAR(20) NOT NULL CHECK (role IN ('USER', 'ASSISTANT', 'SYSTEM')),
    content TEXT NOT NULL,
    tokens_used INT NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS cv_reviews (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL,
    cv_id UUID NOT NULL,
    overall_score SMALLINT NOT NULL CHECK (overall_score BETWEEN 0 AND 100),
    strengths JSONB NOT NULL,
    suggestions JSONB NOT NULL,
    summary TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS ai_usage_logs (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL,
    feature VARCHAR(50) NOT NULL,
    provider VARCHAR(30) NOT NULL,
    model VARCHAR(60) NOT NULL,
    prompt_tokens INT NOT NULL,
    completion_tokens INT NOT NULL,
    latency_ms INT NOT NULL,
    status VARCHAR(20) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS ai_user_quotas (
    user_id UUID PRIMARY KEY,
    daily_limit INT NOT NULL DEFAULT 50,
    used_today INT NOT NULL DEFAULT 0,
    monthly_token_limit INT NOT NULL DEFAULT 500000,
    monthly_tokens_used INT NOT NULL DEFAULT 0,
    reset_at TIMESTAMPTZ NOT NULL DEFAULT NOW() + interval '1 day',
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 1. 160 Job Recommendations
ON CONFLICT (user_id, job_id) DO NOTHING;

-- 2. 16 Chat Sessions & 128 Chat Messages
ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

-- 3. 16 CV Reviews
ON CONFLICT (id) DO NOTHING;

-- 4. 140 AI Usage Logs
ON CONFLICT (id) DO NOTHING;

-- 5. 51 AI User Quotas (1 per User)
ON CONFLICT (user_id) DO UPDATE SET used_today = EXCLUDED.used_today, monthly_tokens_used = EXCLUDED.monthly_tokens_used, updated_at = NOW();
